using System;
using System.Collections.Generic;
using NaughtyAttributes;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "CharacterOmens", menuName = "Data/Characters/Omens")]
public class CharacterOmens : ScriptableObject
{
	[Serializable]
	public class BlessingsSetInfo
	{
		public string SetId;

		public List<OmenData> Omens;
	}

	[Serializable]
	public class ModBlessingsSetInfo
	{
		public string PublishedId;

		public List<BlessingsSetInfo> BlessingsSetInfosList;

		public ModBlessingsSetInfo(string publishedId)
		{
			PublishedId = publishedId;
			BlessingsSetInfosList = new List<BlessingsSetInfo>();
		}
	}

	[Header("Default Blessings")]
	public List<OmenData> DefaultOmens = new List<OmenData>();

	[Header("Custom Blessings")]
	public List<ModBlessingsSetInfo> CustomOmenList = new List<ModBlessingsSetInfo>();

	[Header("Editor: Build Blessings")]
	[HorizontalLine(2f, EColor.Gray)]
	public List<OmenData> BuildOmens = new List<OmenData>();
}
